import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  OnGatewayConnection,
  OnGatewayDisconnect,
  ConnectedSocket,
  MessageBody,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger, Inject, forwardRef, OnModuleInit } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { ClusterManagerService } from '../services/cluster-manager.service';
import { WorkerTransportGateway } from '../interfaces/worker-transport-gateway.interface';
import { NodeIdentity } from '../contracts/cluster/node-identity.interface';
import { ClusterManifest } from '../contracts/cluster/cluster-manifest.interface';
import { NodeOfflineEvent } from '../events/cluster-events';
import { TaskDispatcherService } from '../../runtime/services/task-dispatcher.service';
import { ExecutionOrchestratorService } from '../../runtime/services/execution-orchestrator.service';
import { ExecutionTransport } from '../../runtime/contracts/execution-transport.interface';
import type {
  TaskEnvelope,
  ResultEnvelope,
  ProgressFrame,
  HeartbeatFrame,
} from '../contracts/execution/envelopes.interface';

@WebSocketGateway({
  namespace: '/cluster',
  cors: { origin: '*' },
})
export class WorkerWebSocketGateway
  implements
    OnGatewayConnection,
    OnGatewayDisconnect,
    WorkerTransportGateway,
    ExecutionTransport,
    OnModuleInit
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(WorkerWebSocketGateway.name);
  private readonly nodeSockets = new Map<string, string>();
  private readonly socketNodes = new Map<string, string>();

  constructor(
    @Inject(forwardRef(() => ClusterManagerService))
    private readonly clusterManager: ClusterManagerService,
    private readonly eventEmitter: EventEmitter2,
    private readonly taskDispatcher: TaskDispatcherService,
    private readonly executionOrchestrator: ExecutionOrchestratorService,
  ) {}

  onModuleInit() {
    this.taskDispatcher.registerTransport(this);
  }

  async handleConnection(client: Socket) {
    this.logger.log(
      `Client connected: ${client.id}. Waiting for registration...`,
    );
  }

  async handleDisconnect(client: Socket) {
    const nodeId = this.socketNodes.get(client.id);
    if (nodeId) {
      this.disconnect(nodeId);
    }
  }

  @SubscribeMessage('register')
  handleRegister(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    payload: { identity: NodeIdentity; manifest: ClusterManifest },
  ) {
    const { identity, manifest } = payload;
    const session = this.clusterManager.registerNode(identity, manifest);

    this.nodeSockets.set(identity.nodeId, client.id);
    this.socketNodes.set(client.id, identity.nodeId);
    this.connect(identity.nodeId);

    return { status: 'REGISTERED', sessionId: session.sessionId };
  }

  connect(nodeId: string): void {
    this.logger.log(
      `Node ${nodeId} successfully registered on WebSocket Gateway`,
    );
  }

  disconnect(nodeId: string): void {
    const socketId = this.nodeSockets.get(nodeId);
    if (socketId) {
      this.socketNodes.delete(socketId);
      this.nodeSockets.delete(nodeId);
    }

    try {
      this.clusterManager.removeNodeLease(nodeId);
    } catch {}

    this.eventEmitter.emit(
      NodeOfflineEvent.EVENT_NAME,
      new NodeOfflineEvent(nodeId, 'SOCKET_DISCONNECT', new Date()),
    );
  }

  async dispatchTask(nodeId: string, task: TaskEnvelope): Promise<void> {
    const socketId = this.nodeSockets.get(nodeId);
    if (!socketId) {
      throw new Error(`Node ${nodeId} is not connected`);
    }
    this.server.to(socketId).emit('task.dispatch', task);
  }

  async dispatchExecution(
    workerId: string,
    executionId: string,
    capabilityId: string,
    input: any,
  ): Promise<void> {
    const socketId = this.nodeSockets.get(workerId);
    if (!socketId) {
      throw new Error(`Node ${workerId} is not connected`);
    }

    const task: TaskEnvelope = {
      taskId: executionId,
      capabilityId: capabilityId,
      payload: input,
      traceId: `trace-${executionId}`,
      correlationId: executionId,
      executionId: executionId,
    };

    this.server.to(socketId).emit('task.dispatch', task);
  }

  async cancelTask(workerId: string, executionId: string): Promise<void> {
    const socketId = this.nodeSockets.get(workerId);
    if (socketId) {
      this.server.to(socketId).emit('task.cancel', { executionId });
    }
  }

  onHeartbeat(nodeId: string, frame: HeartbeatFrame): void {
    // Original implementation handled by handleHeartbeatMessage
  }

  onProgress(nodeId: string, frame: ProgressFrame): void {
    // Original implementation handled by handleProgressMessage
  }

  onResult(nodeId: string, result: ResultEnvelope): void {
    // Original implementation handled by handleResultMessage
  }

  @SubscribeMessage('heartbeat')
  handleHeartbeatMessage(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: unknown,
  ) {
    const frame = payload as HeartbeatFrame;
    const nodeId = this.socketNodes.get(client.id);
    if (nodeId) {
      try {
        this.clusterManager.renewNodeLease(nodeId);
      } catch {
        this.logger.warn(`Could not renew lease for ${nodeId}`);
      }
    }
  }

  @SubscribeMessage('progress')
  handleProgressMessage(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: unknown,
  ) {
    const frame = payload as ProgressFrame;
    const nodeId = this.socketNodes.get(client.id);
    if (nodeId) {
      const execId = frame.executionId || frame.correlationId;
      if (execId) {
        this.executionOrchestrator
          .updateProgress(execId, frame.progress || 0)
          .catch((err) => this.logger.error(err));
      }
    }
  }

  @SubscribeMessage('result')
  handleResultMessage(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: unknown,
  ) {
    const result = payload as ResultEnvelope;
    const nodeId = this.socketNodes.get(client.id);
    if (nodeId) {
      const execId = result.executionId || result.correlationId;
      if (execId) {
        if (result.status === 'SUCCESS') {
          this.executionOrchestrator
            .completeTask(
              execId,
              (result as any).result ??
                (result as any).data ??
                (result as any).payload,
            )
            .catch((err) => this.logger.error(err));
        } else {
          this.executionOrchestrator
            .failTask(execId, result.error)
            .catch((err) => this.logger.error(err));
        }
      }
    }
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { CapabilityRegistryService } from './capability-registry.service';
import { ClusterManifest } from '../../cluster/contracts/cluster/cluster-manifest.interface';

describe('CapabilityRegistryService', () => {
  let service: CapabilityRegistryService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [CapabilityRegistryService],
    }).compile();

    service = module.get<CapabilityRegistryService>(CapabilityRegistryService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  const validWorkerManifest: ClusterManifest = {
    clusterVersion: '1.0',
    minimumWorkerVersion: '1.0',
    supportedProtocols: ['socket.io'],
    worker: {
      id: 'worker-1',
      hostname: 'test-host',
      platform: 'linux',
      arch: 'x64',
      version: '1.0.0',
      startedAt: new Date().toISOString(),
    },
    capabilities: [
      {
        id: 'system.info',
        name: 'System Info',
        version: '1.0.0',
        category: 'system',
        description: 'Get system info',
        platform: ['all'],
        inputSchema: {},
      },
    ],
  };

  describe('worker registration', () => {
    it('should register a worker and its capabilities', () => {
      service.registerWorker(validWorkerManifest);

      const worker = service.getWorker('worker-1');
      expect(worker).toBeDefined();
      expect(worker?.id).toBe('worker-1');
      expect(worker?.capabilityIds).toContain('system.info');

      const cap = service.getCapability('system.info');
      expect(cap).toBeDefined();
      expect(cap?.workerIds).toContain('worker-1');
    });

    it('should skip indexing if no worker manifest is provided (protocol compatibility)', () => {
      const emptyManifest: ClusterManifest = {
        clusterVersion: '1.0',
        minimumWorkerVersion: '1.0',
        supportedProtocols: ['socket.io'],
      };

      expect(() => service.registerWorker(emptyManifest)).not.toThrow();
      expect(service.listWorkers()).toHaveLength(0);
    });

    it('should throw on malformed worker schema', () => {
      const invalidManifest = {
        ...validWorkerManifest,
        worker: { id: 123 } as any, // invalid id type
      };

      expect(() => service.registerWorker(invalidManifest)).toThrow(
        'Malformed worker manifest',
      );
    });

    it('should reject duplicate capability IDs within a single worker', () => {
      const dupManifest = {
        ...validWorkerManifest,
        capabilities: [
          validWorkerManifest.capabilities![0],
          validWorkerManifest.capabilities![0],
        ],
      };

      expect(() => service.registerWorker(dupManifest)).toThrow(
        'Duplicate capability IDs within a single worker',
      );
    });

    it('should allow multiple workers to expose the same capability', () => {
      service.registerWorker(validWorkerManifest);

      const worker2Manifest = {
        ...validWorkerManifest,
        worker: {
          ...validWorkerManifest.worker!,
          id: 'worker-2',
        },
      };

      service.registerWorker(worker2Manifest);

      const workers = service.listWorkers();
      expect(workers).toHaveLength(2);

      const cap = service.getCapability('system.info');
      expect(cap?.workerIds).toHaveLength(2);
      expect(cap?.workerIds).toContain('worker-1');
      expect(cap?.workerIds).toContain('worker-2');
    });

    it('should cleanup old state on reconnect (same worker ID)', () => {
      service.registerWorker(validWorkerManifest);

      // Reconnect with same ID, different capabilities
      const reconnectManifest = {
        ...validWorkerManifest,
        capabilities: [],
      };

      service.registerWorker(reconnectManifest);

      const worker = service.getWorker('worker-1');
      expect(worker?.capabilityIds).toHaveLength(0);

      const cap = service.getCapability('system.info');
      expect(cap).toBeUndefined(); // Should be cleaned up because no workers have it
    });
  });

  describe('worker unregistration', () => {
    it('should remove worker and release capability indexes', () => {
      service.registerWorker(validWorkerManifest);

      service.unregisterWorker('worker-1');

      expect(service.getWorker('worker-1')).toBeUndefined();
      expect(service.getCapability('system.info')).toBeUndefined();
      expect(service.listWorkers()).toHaveLength(0);
      expect(service.listCapabilities()).toHaveLength(0);
    });

    it('should not delete capability if another worker still provides it', () => {
      service.registerWorker(validWorkerManifest);

      const worker2Manifest = {
        ...validWorkerManifest,
        worker: {
          ...validWorkerManifest.worker!,
          id: 'worker-2',
        },
      };

      service.registerWorker(worker2Manifest);
      service.unregisterWorker('worker-1');

      expect(service.getWorker('worker-1')).toBeUndefined();

      const cap = service.getCapability('system.info');
      expect(cap).toBeDefined();
      expect(cap?.workerIds).toContain('worker-2');
      expect(cap?.workerIds).not.toContain('worker-1');
    });
  });

  describe('heartbeat', () => {
    it('should update lastHeartbeat of a worker', () => {
      service.registerWorker(validWorkerManifest);
      const workerBefore = service.getWorker('worker-1');
      const timeBefore = workerBefore?.lastHeartbeat.getTime();

      // simulate time passing
      jest.useFakeTimers();
      jest.advanceTimersByTime(1000);

      service.updateHeartbeat('worker-1');

      const workerAfter = service.getWorker('worker-1');
      expect(workerAfter?.lastHeartbeat.getTime()).toBeGreaterThan(timeBefore!);

      jest.useRealTimers();
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { ExecutionOrchestratorService } from './execution-orchestrator.service';
import { DatabaseService } from '../../../database';
import { TaskExecutionStatus } from '../contracts/execution.dto';

describe('ExecutionOrchestratorService', () => {
  let service: ExecutionOrchestratorService;
  let dbMock: any;
  let eventEmitterMock: any;

  beforeEach(async () => {
    dbMock = {
      db: {
        insert: jest.fn().mockReturnThis(),
        values: jest.fn().mockReturnThis(),
        returning: jest
          .fn()
          .mockResolvedValue([{ id: 'test-id', status: 'PENDING' }]),
        select: jest.fn().mockReturnThis(),
        from: jest.fn().mockReturnThis(),
        where: jest
          .fn()
          .mockResolvedValue([{ id: 'test-id', status: 'QUEUED' }]),
        update: jest.fn().mockReturnThis(),
        set: jest.fn().mockReturnThis(),
      },
    };

    eventEmitterMock = {
      emit: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        ExecutionOrchestratorService,
        { provide: DatabaseService, useValue: dbMock },
        { provide: EventEmitter2, useValue: eventEmitterMock },
      ],
    }).compile();

    service = module.get<ExecutionOrchestratorService>(
      ExecutionOrchestratorService,
    );
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('submitTask', () => {
    it('should create a task and transition to QUEUED', async () => {
      const task = await service.submitTask('user1', 'shell.exec', {
        command: 'ls',
      });
      expect(task).toBeDefined();
      expect(dbMock.db.insert).toHaveBeenCalled();
      expect(dbMock.db.update).toHaveBeenCalled();
      expect(eventEmitterMock.emit).toHaveBeenCalledWith(
        'TaskExecution.QUEUED',
        expect.anything(),
      );
    });
  });

  describe('setRunning', () => {
    it('should start dual timeout and transition to RUNNING', async () => {
      // Mock getExecution for the internal lookup
      dbMock.db.where.mockResolvedValueOnce([
        { id: 'test-id', timeoutMs: 100, status: 'RUNNING' },
      ]);

      await service.setRunning('test-id');

      expect(dbMock.db.update).toHaveBeenCalled();
      expect(eventEmitterMock.emit).toHaveBeenCalledWith(
        'TaskExecution.RUNNING',
        expect.anything(),
      );
    });
  });

  describe('failTask', () => {
    it('should retry if attempts < maxRetries', async () => {
      dbMock.db.where.mockResolvedValueOnce([
        { id: 'test-id', attempts: 0, maxRetries: 3 },
      ]);

      await service.failTask('test-id', { message: 'Network error' });

      expect(dbMock.db.update).toHaveBeenCalled(); // Increment attempt
      expect(eventEmitterMock.emit).toHaveBeenCalledWith(
        'TaskExecution.RETRYING',
        expect.anything(),
      );
    });

    it('should fail if maxRetries reached', async () => {
      dbMock.db.where.mockResolvedValueOnce([
        { id: 'test-id', attempts: 3, maxRetries: 3 },
      ]);

      await service.failTask('test-id', { message: 'Network error' });

      expect(eventEmitterMock.emit).toHaveBeenCalledWith(
        'TaskExecution.FAILED',
        expect.anything(),
      );
    });
  });
});

import { Injectable, Logger, Inject } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { DatabaseService } from '../../../database';
import { taskExecutions } from '@jarvis/database';
import { eq } from 'drizzle-orm';
import { TaskExecutionStatus, TaskExecution } from '../contracts/execution.dto';
import {
  ExecutionCreatedEvent,
  ExecutionStartedEvent,
  ExecutionProgressEvent,
  ExecutionCompletedEvent,
  ExecutionFailedEvent,
  ExecutionTimedOutEvent,
  ExecutionCancelledEvent,
} from '../events/execution.events';

@Injectable()
export class ExecutionOrchestratorService {
  private readonly logger = new Logger(ExecutionOrchestratorService.name);
  private readonly executionTimeouts = new Map<string, NodeJS.Timeout>();

  constructor(
    private readonly database: DatabaseService,
    private readonly eventEmitter: EventEmitter2,
  ) {}

  async submitTask(
    userId: string,
    capabilityId: string,
    input: any,
    timeoutMs: number = 60000,
    maxRetries: number = 0,
  ): Promise<TaskExecution> {
    const [record] = await this.database.db
      .insert(taskExecutions)
      .values({
        userId,
        capabilityId,
        input,
        timeoutMs,
        maxRetries,
        status: 'PENDING',
      })
      .returning();

    this.logger.log(
      `Task ${record.id} submitted for capability ${capabilityId}`,
    );

    this.eventEmitter.emit(
      ExecutionCreatedEvent.name,
      new ExecutionCreatedEvent(record.id),
    );

    // Transition to QUEUED to kick off dispatch
    await this.updateStatus(record.id, TaskExecutionStatus.QUEUED);

    return this.mapToDTO(record);
  }

  async getExecution(id: string): Promise<TaskExecution | null> {
    const [record] = await this.database.db
      .select()
      .from(taskExecutions)
      .where(eq(taskExecutions.id, id));
    if (!record) return null;
    return this.mapToDTO(record);
  }

  async setPlanned(id: string, workerId: string): Promise<void> {
    await this.updateStatus(id, TaskExecutionStatus.PLANNED, { workerId });
  }

  async setDispatched(id: string): Promise<void> {
    await this.updateStatus(id, TaskExecutionStatus.DISPATCHED);
  }

  async setRunning(id: string): Promise<void> {
    await this.updateStatus(id, TaskExecutionStatus.RUNNING, {
      startedAt: new Date(),
    });

    // Start dual timeout tracker
    const execution = await this.getExecution(id);
    if (execution && execution.timeoutMs) {
      this.startTimeTracker(id, execution.timeoutMs);
    }
  }

  async updateProgress(id: string, progress: number): Promise<void> {
    await this.database.db
      .update(taskExecutions)
      .set({ progress, updatedAt: new Date() })
      .where(eq(taskExecutions.id, id));
    this.eventEmitter.emit(
      ExecutionProgressEvent.name,
      new ExecutionProgressEvent(id, progress),
    );
  }

  async completeTask(id: string, output: any): Promise<void> {
    const execution = await this.getExecution(id);
    if (!execution || this.isTerminalState(execution.status)) return;
    this.stopTimeTracker(id);
    await this.updateStatus(id, TaskExecutionStatus.SUCCESS, {
      output,
      completedAt: new Date(),
      progress: 100,
    });
  }

  async failTask(id: string, error: any): Promise<void> {
    const execution = await this.getExecution(id);
    if (!execution || this.isTerminalState(execution.status)) return;

    this.stopTimeTracker(id);

    if (execution.attempts < execution.maxRetries) {
      this.logger.warn(
        `Task ${id} failed (attempt ${execution.attempts}). Retrying...`,
      );
      await this.database.db
        .update(taskExecutions)
        .set({ attempts: execution.attempts + 1, error, updatedAt: new Date() })
        .where(eq(taskExecutions.id, id));
      await this.updateStatus(id, TaskExecutionStatus.RETRYING);

      // Re-queue after brief delay
      setTimeout(() => {
        this.updateStatus(id, TaskExecutionStatus.QUEUED);
      }, 1000);
    } else {
      await this.updateStatus(id, TaskExecutionStatus.FAILED, {
        error,
        completedAt: new Date(),
      });
    }
  }

  async cancelTask(id: string): Promise<void> {
    const execution = await this.getExecution(id);
    if (!execution || this.isTerminalState(execution.status)) return;
    this.stopTimeTracker(id);
    await this.updateStatus(id, TaskExecutionStatus.CANCELLED, {
      completedAt: new Date(),
    });
  }

  async abortTask(id: string, reason: string): Promise<void> {
    const execution = await this.getExecution(id);
    if (!execution || this.isTerminalState(execution.status)) return;
    this.stopTimeTracker(id);
    await this.updateStatus(id, TaskExecutionStatus.ABORTED, {
      error: { message: reason },
      completedAt: new Date(),
    });
  }

  private isTerminalState(status: TaskExecutionStatus): boolean {
    return [
      TaskExecutionStatus.SUCCESS,
      TaskExecutionStatus.FAILED,
      TaskExecutionStatus.CANCELLED,
      TaskExecutionStatus.ABORTED,
      TaskExecutionStatus.TIMED_OUT,
    ].includes(status);
  }

  private startTimeTracker(id: string, timeoutMs: number) {
    this.stopTimeTracker(id);
    const timeout = setTimeout(async () => {
      this.logger.warn(
        `Task ${id} timed out after ${timeoutMs}ms (Core Enforcement)`,
      );
      await this.updateStatus(id, TaskExecutionStatus.TIMED_OUT, {
        completedAt: new Date(),
      });
    }, timeoutMs);
    this.executionTimeouts.set(id, timeout);
  }

  private stopTimeTracker(id: string) {
    const timeout = this.executionTimeouts.get(id);
    if (timeout) {
      clearTimeout(timeout);
      this.executionTimeouts.delete(id);
    }
  }

  private async updateStatus(
    id: string,
    status: TaskExecutionStatus,
    extraFields: any = {},
  ): Promise<void> {
    await this.database.db
      .update(taskExecutions)
      .set({ status, updatedAt: new Date(), ...extraFields })
      .where(eq(taskExecutions.id, id));

    this.logger.log(`Task ${id} -> ${status}`);
    const updated = await this.getExecution(id);

    // Also emit the old dynamic event for backward-compatibility with generic listeners like TaskDispatcherService
    this.eventEmitter.emit(`TaskExecution.${status}`, updated);

    if (updated) {
      if (status === TaskExecutionStatus.RUNNING) {
        this.eventEmitter.emit(
          ExecutionStartedEvent.name,
          new ExecutionStartedEvent(id),
        );
      } else if (status === TaskExecutionStatus.SUCCESS) {
        this.eventEmitter.emit(
          ExecutionCompletedEvent.name,
          new ExecutionCompletedEvent(id, updated.output),
        );
      } else if (
        status === TaskExecutionStatus.FAILED ||
        status === TaskExecutionStatus.ABORTED
      ) {
        this.eventEmitter.emit(
          ExecutionFailedEvent.name,
          new ExecutionFailedEvent(id, updated.error),
        );
      } else if (status === TaskExecutionStatus.TIMED_OUT) {
        this.eventEmitter.emit(
          ExecutionTimedOutEvent.name,
          new ExecutionTimedOutEvent(id),
        );
      } else if (status === TaskExecutionStatus.CANCELLED) {
        this.eventEmitter.emit(
          ExecutionCancelledEvent.name,
          new ExecutionCancelledEvent(id),
        );
      }
    }
  }

  private mapToDTO(record: any): TaskExecution {
    return {
      id: record.id,
      userId: record.userId,
      capabilityId: record.capabilityId,
      status: record.status as TaskExecutionStatus,
      input: record.input,
      output: record.output,
      error: record.error,
      workerId: record.workerId,
      progress: record.progress,
      attempts: record.attempts,
      maxRetries: record.maxRetries,
      timeoutMs: record.timeoutMs,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt,
      startedAt: record.startedAt,
      completedAt: record.completedAt,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { ExecutionOrchestratorService } from './execution-orchestrator.service';
import { TaskPlannerService } from './task-planner.service';
import { TaskExecutionStatus } from '../contracts/execution.dto';
import type { TaskExecution } from '../contracts/execution.dto';
import type { ExecutionTransport } from '../contracts/execution-transport.interface';

@Injectable()
export class TaskDispatcherService {
  private readonly logger = new Logger(TaskDispatcherService.name);
  private transports: ExecutionTransport[] = [];

  constructor(
    private readonly orchestrator: ExecutionOrchestratorService,
    private readonly planner: TaskPlannerService,
  ) {}

  registerTransport(transport: ExecutionTransport) {
    this.transports.push(transport);
  }

  @OnEvent('TaskExecution.QUEUED')
  async handleTaskQueued(execution: TaskExecution) {
    this.logger.log(
      `Dispatching task ${execution.id} for capability ${execution.capabilityId}`,
    );

    if (this.transports.length === 0) {
      this.logger.error(
        `No transports registered. Cannot dispatch ${execution.id}`,
      );
      await this.orchestrator.abortTask(
        execution.id,
        'No transports available',
      );
      return;
    }

    try {
      const plan = await this.planner.planTask({
        capabilityId: execution.capabilityId,
        input: execution.input,
      });

      if (!plan || !plan.workerId) {
        throw new Error('No capable workers found');
      }

      await this.orchestrator.setPlanned(execution.id, plan.workerId);

      // Dispatch to the first registered transport (we assume WebSocket Gateway for now)
      const transport = this.transports[0];
      await transport.dispatchExecution(
        plan.workerId,
        execution.id,
        execution.capabilityId,
        execution.input,
      );

      await this.orchestrator.setDispatched(execution.id);
    } catch (err: any) {
      this.logger.error(
        `Dispatch failed for task ${execution.id}: ${err.message}`,
      );
      await this.orchestrator.failTask(execution.id, { message: err.message });
    }
  }

  @OnEvent('TaskExecution.CANCELLED')
  async handleTaskCancelled(execution: TaskExecution) {
    if (!execution.workerId) return; // Cannot cancel unassigned tasks on worker

    if (this.transports.length > 0) {
      try {
        await this.transports[0].cancelTask(execution.workerId, execution.id);
      } catch (err: any) {
        this.logger.error(
          `Failed to send cancel signal for task ${execution.id} to worker ${execution.workerId}: ${err.message}`,
        );
      }
    }
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { TaskPlannerService } from './task-planner.service';
import { CapabilityRegistryService } from './capability-registry.service';
import {
  CapabilityNotFoundException,
  NoEligibleWorkerException,
  PlannerValidationException,
} from '../exceptions/planner.exceptions';

describe('TaskPlannerService', () => {
  let planner: TaskPlannerService;
  let registry: jest.Mocked<CapabilityRegistryService>;

  beforeEach(async () => {
    // Create a mock for CapabilityRegistryService
    const registryMock = {
      getCapability: jest.fn(),
      getWorker: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        TaskPlannerService,
        {
          provide: CapabilityRegistryService,
          useValue: registryMock,
        },
      ],
    }).compile();

    planner = module.get<TaskPlannerService>(TaskPlannerService);
    registry = module.get(CapabilityRegistryService);
  });

  it('should throw PlannerValidationException if capabilityId is missing', () => {
    expect(() => planner.planTask({ capabilityId: '', input: {} })).toThrow(
      PlannerValidationException,
    );
  });

  it('should throw CapabilityNotFoundException if capability is not in registry', () => {
    registry.getCapability.mockReturnValue(undefined);

    expect(() =>
      planner.planTask({ capabilityId: 'unknown.cap', input: {} }),
    ).toThrow(CapabilityNotFoundException);
    expect(registry.getCapability).toHaveBeenCalledWith('unknown.cap');
  });

  it('should throw NoEligibleWorkerException if capability has no workers', () => {
    registry.getCapability.mockReturnValue({ workerIds: [] } as any);

    expect(() =>
      planner.planTask({ capabilityId: 'system.info', input: {} }),
    ).toThrow(NoEligibleWorkerException);
  });

  it('should throw NoEligibleWorkerException if matching workers are OFFLINE', () => {
    registry.getCapability.mockReturnValue({ workerIds: ['worker-1'] } as any);
    registry.getWorker.mockReturnValue({
      id: 'worker-1',
      status: 'OFFLINE',
    } as any);

    expect(() =>
      planner.planTask({ capabilityId: 'system.info', input: {} }),
    ).toThrow(NoEligibleWorkerException);
  });

  it('should successfully plan task for a single ACTIVE worker', () => {
    registry.getCapability.mockReturnValue({ workerIds: ['worker-1'] } as any);
    registry.getWorker.mockReturnValue({
      id: 'worker-1',
      status: 'ACTIVE',
    } as any);

    const plan = planner.planTask({ capabilityId: 'system.info', input: {} });
    expect(plan.workerId).toBe('worker-1');
    expect(plan.capabilityId).toBe('system.info');
    expect(plan.reason).toBeDefined();
  });

  it('should deterministically select the first ACTIVE worker when multiple qualify', () => {
    registry.getCapability.mockReturnValue({
      workerIds: ['worker-b', 'worker-a', 'worker-c'],
    } as any);
    registry.getWorker.mockImplementation(
      (id: string) => ({ id, status: 'ACTIVE' }) as any,
    );

    const plan1 = planner.planTask({ capabilityId: 'system.info', input: {} });
    const plan2 = planner.planTask({ capabilityId: 'system.info', input: {} });

    // Based on deterministic sorting in FirstAvailableStrategy, 'worker-a' should be chosen
    expect(plan1.workerId).toBe('worker-a');
    expect(plan2.workerId).toBe('worker-a');
  });

  it('should skip offline workers and select an ACTIVE one', () => {
    registry.getCapability.mockReturnValue({
      workerIds: ['worker-a', 'worker-b'],
    } as any);

    registry.getWorker.mockImplementation((id: string) => {
      if (id === 'worker-a') return { id, status: 'OFFLINE' } as any;
      if (id === 'worker-b') return { id, status: 'ACTIVE' } as any;
      return undefined;
    });

    const plan = planner.planTask({ capabilityId: 'system.info', input: {} });

    expect(plan.workerId).toBe('worker-b');
  });
});

