export class WorkflowPlanningError extends Error {
  constructor(
    message: string,
    public readonly metadata: WorkflowPlanningMetadata,
  ) {
    super(message);
    this.name = 'WorkflowPlanningError';
  }
}

@Injectable()
export class WorkflowPlannerService {
  private readonly logger = new Logger(WorkflowPlannerService.name);
  private readonly promptVersion = '1.0.0';

  constructor(
    private readonly inferenceService: InferenceService,
    private readonly validatorService: WorkflowValidatorService,
    private readonly capabilityRegistry: CapabilityRegistryService,
  ) {}

  public async plan(
    goal: string,
    provider: InferenceProviderType = InferenceProviderType.OLLAMA,
    model: string = 'llama3',
  ): Promise<WorkflowDefinition> {
    const startTime = Date.now();
    let repairAttempts = 0;

    const metadata: WorkflowPlanningMetadata = {
      provider,
      model,
      promptVersion: this.promptVersion,
      repairAttempts,
      validationResult: 'SUCCESS',
      planningTimeMs: 0,
    };

    try {
      const prompt = this.buildPrompt(goal);
      const response = await this.invokeLLM(provider, prompt, model);
      const parsedDefinition = this.parseResponse(response);

      const validation = this.validatorService.validate(parsedDefinition);

      if (!validation.valid) {
        this.logger.warn(
          `Initial workflow validation failed: ${validation.errors.join(', ')}. Attempting repair...`,
        );
        repairAttempts++;
        metadata.repairAttempts = repairAttempts;

        const repairPrompt = this.buildRepairPrompt(
          goal,
          response,
          validation.errors,
        );
        const repairResponse = await this.invokeLLM(
          provider,
          repairPrompt,
          model,
        );
        const repairedDefinition = this.parseResponse(repairResponse);

        const repairValidation =
          this.validatorService.validate(repairedDefinition);
        if (!repairValidation.valid) {
          metadata.validationResult = 'FAILED';
          metadata.planningTimeMs = Date.now() - startTime;
          throw new WorkflowPlanningError(
            `Workflow repair failed: ${repairValidation.errors.join(', ')}`,
            metadata,
          );
        }

        metadata.validationResult = 'REPAIRED';
        repairedDefinition.planningMetadata = metadata;
        repairedDefinition.planningMetadata.planningTimeMs =
          Date.now() - startTime;
        return repairedDefinition;
      }

      metadata.planningTimeMs = Date.now() - startTime;
      parsedDefinition.planningMetadata = metadata;
      return parsedDefinition;
    } catch (e: any) {
      if (e instanceof WorkflowPlanningError) {
        throw e;
      }

      metadata.validationResult = 'FAILED';
      metadata.planningTimeMs = Date.now() - startTime;
      throw new WorkflowPlanningError(
        e.message || 'Unknown planning error',
        metadata,
      );
    }
  }

  private buildPrompt(goal: string): string {
    const capabilities = this.capabilityRegistry.listCapabilities();
    const capabilitiesJson = JSON.stringify(
      capabilities.map((c) => ({
        id: c.id,
        description: c.description,
      })),
      null,
      2,
    );

    return `You are a Workflow Planner for Jarvis.
Your task is to convert a natural language goal into a Directed Acyclic Graph (DAG) workflow definition.

Goal: "${goal}"

Available Capabilities:
${capabilitiesJson}

Requirements:
1. Return ONLY valid JSON containing a "steps" array. Do not include markdown blocks like \`\`\`json.
2. Each step must have: "id" (string), "capabilityId" (string), "input" (object), "dependencies" (string array).
3. "dependencies" must contain IDs of steps that must complete before this step.
4. You can pass variables from upstream steps to downstream steps using the exact string syntax: "\${step_id.output.property}".
5. Any step referenced in a variable interpolation MUST be in the "dependencies" array of the step using it.

Example JSON:
{
  "steps": [
    {
      "id": "fetch_data",
      "capabilityId": "filesystem.read",
      "input": { "path": "/tmp/data.txt" },
      "dependencies": []
    },
    {
      "id": "process_data",
      "capabilityId": "shell.exec",
      "input": { "command": "echo \\"\${fetch_data.output.content}\\" | grep ERROR" },
      "dependencies": ["fetch_data"]
    }
  ]
}`;
  }

  private buildRepairPrompt(
    goal: string,
    previousResponse: string,
    errors: string[],
  ): string {
    return `You are a Workflow Planner for Jarvis.
You previously generated a workflow definition that failed validation.

Goal: "${goal}"

Previous Output:
${previousResponse}

Validation Errors:
${errors.map((e) => `- ${e}`).join('\n')}

Fix the workflow definition and return ONLY the corrected valid JSON containing the "steps" array.`;
  }

  private async invokeLLM(
    provider: InferenceProviderType,
    prompt: string,
    model: string,
  ): Promise<string> {
    const response = await this.inferenceService.infer(provider, {
      modelId: model,
      prompt,
      maxTokens: 2000,
      temperature: 0.1,
    });

    // Fallback if the payload is complex or text-based
    if (typeof response.content === 'string') {
      return response.content;
    } else if (
      response.content &&
      typeof response.content === 'object' &&
      'text' in (response.content as any)
    ) {
      return (response.content as any).text;
    }

    // In case the provider wraps it differently
    return JSON.stringify(response.content);
  }

  private parseResponse(response: string): WorkflowDefinition {
    // Strip markdown JSON wrappers if they exist
    let cleaned = response.trim();
    if (cleaned.startsWith('\`\`\`json')) {
      cleaned = cleaned.substring(7);
    } else if (cleaned.startsWith('\`\`\`')) {
      cleaned = cleaned.substring(3);
    }
    if (cleaned.endsWith('\`\`\`')) {
      cleaned = cleaned.substring(0, cleaned.length - 3);
    }

    try {
      return JSON.parse(cleaned) as WorkflowDefinition;
    } catch (e) {
      throw new Error(`Failed to parse LLM response as JSON: ${e}`);
    }
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { WorkflowValidatorService } from './workflow-validator.service';
import { CapabilityRegistryService } from './capability-registry.service';

describe('WorkflowValidatorService', () => {
  let service: WorkflowValidatorService;
  let registryMock: any;

  beforeEach(async () => {
    registryMock = {
      getCapability: jest.fn().mockImplementation((id: string) => {
        if (id === 'valid-cap') return { id: 'valid-cap' };
        return undefined;
      }),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        WorkflowValidatorService,
        { provide: CapabilityRegistryService, useValue: registryMock },
      ],
    }).compile();

    service = module.get<WorkflowValidatorService>(WorkflowValidatorService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  it('should validate a correct workflow', () => {
    const def = {
      steps: [
        { id: '1', capabilityId: 'valid-cap', input: {}, dependencies: [] },
        {
          id: '2',
          capabilityId: 'valid-cap',
          input: { arg: '${1.output.result}' },
          dependencies: ['1'],
        },
      ],
    };
    const res = service.validate(def);
    expect(res.valid).toBe(true);
  });

  it('should invalidate duplicate step ids', () => {
    const def = {
      steps: [
        { id: '1', capabilityId: 'valid-cap', input: {}, dependencies: [] },
        { id: '1', capabilityId: 'valid-cap', input: {}, dependencies: [] },
      ],
    };
    const res = service.validate(def);
    expect(res.valid).toBe(false);
    expect(res.errors[0]).toContain('Duplicate step id found');
  });

  it('should invalidate unknown capabilities', () => {
    const def = {
      steps: [
        { id: '1', capabilityId: 'unknown-cap', input: {}, dependencies: [] },
      ],
    };
    const res = service.validate(def);
    expect(res.valid).toBe(false);
    expect(res.errors[0]).toContain('Unknown capability required: unknown-cap');
  });

  it('should invalidate unknown dependencies', () => {
    const def = {
      steps: [
        { id: '1', capabilityId: 'valid-cap', input: {}, dependencies: ['2'] },
      ],
    };
    const res = service.validate(def);
    expect(res.valid).toBe(false);
    expect(res.errors[0]).toContain('declares an unknown dependency: 2');
  });

  it('should invalidate cyclic dependencies', () => {
    const def = {
      steps: [
        { id: '1', capabilityId: 'valid-cap', input: {}, dependencies: ['2'] },
        { id: '2', capabilityId: 'valid-cap', input: {}, dependencies: ['1'] },
      ],
    };
    const res = service.validate(def);
    expect(res.valid).toBe(false);
    expect(res.errors[0]).toContain('Cycle detected');
  });

  it('should invalidate variables that do not reference upstream dependencies', () => {
    const def = {
      steps: [
        { id: '1', capabilityId: 'valid-cap', input: {}, dependencies: [] },
        {
          id: '2',
          capabilityId: 'valid-cap',
          input: { arg: '${1.output.result}' },
          dependencies: [],
        },
      ],
    };
    const res = service.validate(def);
    expect(res.valid).toBe(false);
    expect(res.errors[0]).toContain(
      'references 1 which is not an upstream dependency',
    );
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { WorkflowDefinition, WorkflowStep } from '../contracts/workflow.dto';
import { CapabilityRegistryService } from './capability-registry.service';

export class WorkflowValidationError extends Error {
  constructor(
    message: string,
    public readonly stepId?: string,
  ) {
    super(message);
    this.name = 'WorkflowValidationError';
  }
}

@Injectable()
export class WorkflowValidatorService {
  private readonly logger = new Logger(WorkflowValidatorService.name);

  constructor(private readonly capabilityRegistry: CapabilityRegistryService) {}

  public validate(definition: WorkflowDefinition): {
    valid: boolean;
    errors: string[];
  } {
    const errors: string[] = [];

    try {
      this.validateStructure(definition);
      this.validateCapabilities(definition);
      this.validateDependencies(definition);
      this.validateCycles(definition);
      this.validateVariables(definition);
    } catch (e: any) {
      if (e instanceof WorkflowValidationError) {
        errors.push(e.message);
      } else {
        errors.push(e.message || 'Unknown validation error');
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  private validateStructure(definition: WorkflowDefinition) {
    if (!definition || !definition.steps || !Array.isArray(definition.steps)) {
      throw new WorkflowValidationError(
        'Workflow definition must contain a steps array',
      );
    }

    const stepIds = new Set<string>();
    for (const step of definition.steps) {
      if (!step.id)
        throw new WorkflowValidationError('Every step must have an id');
      if (!step.capabilityId)
        throw new WorkflowValidationError(
          `Step ${step.id} must have a capabilityId`,
          step.id,
        );

      if (stepIds.has(step.id)) {
        throw new WorkflowValidationError(
          `Duplicate step id found: ${step.id}`,
          step.id,
        );
      }
      stepIds.add(step.id);
    }
  }

  private validateCapabilities(definition: WorkflowDefinition) {
    for (const step of definition.steps) {
      const capability = this.capabilityRegistry.getCapability(
        step.capabilityId,
      );
      if (!capability) {
        throw new WorkflowValidationError(
          `Unknown capability required: ${step.capabilityId}`,
          step.id,
        );
      }
    }
  }

  private validateDependencies(definition: WorkflowDefinition) {
    const stepIds = new Set(definition.steps.map((s) => s.id));
    for (const step of definition.steps) {
      if (step.dependencies) {
        for (const dep of step.dependencies) {
          if (!stepIds.has(dep)) {
            throw new WorkflowValidationError(
              `Step ${step.id} declares an unknown dependency: ${dep}`,
              step.id,
            );
          }
        }
      }
    }
  }

  private validateCycles(definition: WorkflowDefinition) {
    // Basic DFS cycle detection
    const adj = new Map<string, string[]>();
    for (const step of definition.steps) {
      adj.set(step.id, step.dependencies || []);
    }

    const visiting = new Set<string>();
    const visited = new Set<string>();

    const visit = (node: string) => {
      if (visiting.has(node)) {
        throw new WorkflowValidationError(
          `Cycle detected involving step ${node}`,
          node,
        );
      }
      if (visited.has(node)) return;

      visiting.add(node);
      const deps = adj.get(node) || [];
      for (const dep of deps) {
        visit(dep);
      }
      visiting.delete(node);
      visited.add(node);
    };

    for (const step of definition.steps) {
      if (!visited.has(step.id)) {
        visit(step.id);
      }
    }
  }

  private validateVariables(definition: WorkflowDefinition) {
    // Ensure interpolated variables like ${step1.output.foo} reference a valid upstream dependency
    // NOTE: For strict validation, the referenced step MUST be in the dependency chain (either direct or indirect)

    // First, build indirect dependency map
    const adj = new Map<string, string[]>();
    for (const step of definition.steps) {
      adj.set(step.id, step.dependencies || []);
    }

    const getAllAncestors = (
      node: string,
      memo: Map<string, Set<string>> = new Map(),
    ): Set<string> => {
      if (memo.has(node)) return memo.get(node)!;
      const ancestors = new Set<string>();
      const deps = adj.get(node) || [];
      for (const dep of deps) {
        ancestors.add(dep);
        for (const ind of getAllAncestors(dep, memo)) {
          ancestors.add(ind);
        }
      }
      memo.set(node, ancestors);
      return ancestors;
    };

    const memo = new Map<string, Set<string>>();
    for (const step of definition.steps) {
      const ancestors = getAllAncestors(step.id, memo);

      const checkNode = (obj: any) => {
        if (typeof obj === 'string') {
          const matches = obj.matchAll(/\$\{([^}]+)\}/g);
          for (const match of matches) {
            const path = match[1];
            const targetStepId = path.split('.')[0];
            if (!ancestors.has(targetStepId)) {
              throw new WorkflowValidationError(
                `Variable interpolation "${match[0]}" in step ${step.id} references ${targetStepId} which is not an upstream dependency.`,
                step.id,
              );
            }
          }
        } else if (Array.isArray(obj)) {
          obj.forEach(checkNode);
        } else if (obj !== null && typeof obj === 'object') {
          for (const val of Object.values(obj)) {
            checkNode(val);
          }
        }
      };

      checkNode(step.input);
    }
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import request from 'supertest';
import { App } from 'supertest/types';
import { AppModule } from './../src/app.module';
import { ChildProcess, spawn } from 'child_process';
import * as path from 'path';
import { ExecutionOrchestratorService } from '../src/modules/runtime/services/execution-orchestrator.service';
import { CapabilityRegistryService } from '../src/modules/runtime/services/capability-registry.service';
import { DatabaseService } from '../src/database/database.service';
import { users } from '@jarvis/database';
import { randomUUID } from 'crypto';

describe('End-to-End Execution Pipeline (e2e)', () => {
  jest.setTimeout(30000);

  let app: INestApplication<App>;
  let workerProcess: ChildProcess;
  let orchestrator: ExecutionOrchestratorService;
  let capabilityRegistry: CapabilityRegistryService;
  let db: DatabaseService;
  let testUserId: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    await app.init();

    // Start Nest HTTP server on a specific port for the worker to connect to
    await app.listen(4001);

    orchestrator = app.get(ExecutionOrchestratorService);
    capabilityRegistry = app.get(CapabilityRegistryService);
    db = app.get(DatabaseService);

    testUserId = randomUUID();
    await db.db.insert(users).values({
      id: testUserId,
      email: `${testUserId}@example.com`,
      passwordHash: 'dummy',
      role: 'USER',
    });

    // Spawn the worker node process
    const workerPath = path.resolve(
      __dirname,
      '../../worker-node/dist/main.js',
    );
    workerProcess = spawn('node', [workerPath], {
      env: {
        ...process.env,
        CORE_SERVER_URL: 'ws://localhost:4001/cluster',
      },
      stdio: 'pipe',
    });

    workerProcess.stdout?.on('data', (data) =>
      console.log(`Worker stdout: ${data}`),
    );
    workerProcess.stderr?.on('data', (data) =>
      console.error(`Worker stderr: ${data}`),
    );

    // Wait 3 seconds for the worker to fully register and propagate via events
    await new Promise((resolve) => setTimeout(resolve, 3000));
  });

  afterAll(async () => {
    if (workerProcess) {
      workerProcess.kill('SIGTERM');
    }
    await app.close();
  });

  it('should successfully execute system.info on the worker', async () => {
    // We submit a task directly to the orchestrator to verify the dispatch -> worker -> result pipeline
    const task = await orchestrator.submitTask(
      testUserId,
      'system.info',
      {},
      10000,
      0,
    );

    expect(task.id).toBeDefined();

    // Poll for completion
    let completedTask = null;
    for (let i = 0; i < 20; i++) {
      completedTask = await orchestrator.getExecution(task.id);
      if (
        completedTask?.status === 'SUCCESS' ||
        completedTask?.status === 'FAILED'
      ) {
        break;
      }
      await new Promise((resolve) => setTimeout(resolve, 500));
    }

    expect(completedTask).toBeDefined();
    expect(completedTask?.status).toBe('SUCCESS');
    expect(completedTask?.output).toBeDefined();
    console.log(
      'system.info output:',
      JSON.stringify(completedTask?.output, null, 2),
    );
    expect(completedTask?.output?.system?.platform).toBeDefined();
    expect(completedTask?.output?.system?.arch).toBeDefined();
  }, 15000);

  it('should successfully execute filesystem.read on the worker', async () => {
    const task = await orchestrator.submitTask(
      testUserId,
      'filesystem.read',
      { path: 'package.json' },
      10000,
      0,
    );

    // Poll for completion
    let completedTask = null;
    for (let i = 0; i < 20; i++) {
      completedTask = await orchestrator.getExecution(task.id);
      if (
        completedTask?.status === 'SUCCESS' ||
        completedTask?.status === 'FAILED'
      ) {
        break;
      }
      await new Promise((resolve) => setTimeout(resolve, 500));
    }

    expect(completedTask?.status).toBe('SUCCESS');
    expect(completedTask?.output?.content).toBeDefined();
    console.log(
      'filesystem.read output:',
      JSON.stringify(completedTask?.output, null, 2),
    );
    expect(completedTask?.output?.content).toContain('api');
  }, 15000);
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import { AppModule } from './../src/app.module';
import { ChildProcess, spawn } from 'child_process';
import * as path from 'path';
import { WorkflowEngineService } from '../src/modules/runtime/services/workflow-engine.service';
import { WorkflowPlannerService } from '../src/modules/runtime/services/workflow-planner.service';
import { CapabilityRegistryService } from '../src/modules/registry/capability-registry.service';
import { InferenceService } from '../src/modules/workers/inference/services/inference.service';
import { DatabaseService } from '../src/database/database.service';
import { users, workflowExecutions } from '@jarvis/database';
import { randomUUID } from 'crypto';
import { eq } from 'drizzle-orm';
import { WorkflowExecutionStatus } from '../src/modules/runtime/contracts/workflow.dto';

describe('End-to-End Smoke Test Pipeline (e2e)', () => {
  jest.setTimeout(45000); // 45s timeout to let all tasks run

  let app: INestApplication;
  let workerProcess: ChildProcess;
  let workflowEngine: WorkflowEngineService;
  let workflowPlanner: WorkflowPlannerService;
  let inferenceService: InferenceService;
  let db: DatabaseService;
  let testUserId: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    await app.init();

    // Start Nest HTTP server on a specific port for the worker to connect to
    await app.listen(4002); // 4002 to avoid conflicts if another runs on 4001

    workflowEngine = app.get(WorkflowEngineService);
    workflowPlanner = app.get(WorkflowPlannerService);
    inferenceService = app.get(InferenceService);
    db = app.get(DatabaseService);

    testUserId = randomUUID();
    await db.db.insert(users).values({
      id: testUserId,
      email: `${testUserId}@smoke.com`,
      passwordHash: 'dummy',
      role: 'USER',
    });

    // Spawn the worker node process
    const workerPath = path.resolve(
      __dirname,
      '../../worker-node/dist/main.js',
    );
    workerProcess = spawn('node', [workerPath], {
      env: {
        ...process.env,
        CORE_SERVER_URL: 'ws://localhost:4002/cluster',
      },
      stdio: 'pipe',
    });

    workerProcess.stdout?.on('data', (data) =>
      console.log(`Worker stdout: ${data}`),
    );
    workerProcess.stderr?.on('data', (data) =>
      console.error(`Worker stderr: ${data}`),
    );

    // Wait for the worker to fully register and capabilities to load
    for (let i = 0; i < 30; i++) {
      const registry = app.get(CapabilityRegistryService);
      const caps = registry.getAllDefinitions();
      if (
        caps.find((c) => c.id === 'system.info') &&
        caps.find((c) => c.id === 'process.spawn')
      ) {
        break;
      }
      await new Promise((resolve) => setTimeout(resolve, 1000));
    }
  });

  afterAll(async () => {
    if (workerProcess) {
      workerProcess.kill('SIGTERM');
    }
    // Delete test user to clean up DB
    await db.db.delete(users).where(eq(users.id, testUserId));
    await app.close();
  });

  it('should successfully plan and execute a complete workflow', async () => {
    // 1. Mock the InferenceService to return a predetermined workflow plan JSON
    const mockWorkflowJson = JSON.stringify({
      steps: [
        {
          id: 'step_info',
          capabilityId: 'system.info',
          input: {},
          dependencies: [],
        },
        {
          id: 'step_write',
          capabilityId: 'filesystem.write',
          input: {
            path: 'smoke-test-file.txt',
            content: 'hello from workflow',
            overwrite: true,
          },
          dependencies: [],
        },
        {
          id: 'step_read',
          capabilityId: 'filesystem.read',
          input: {
            path: 'smoke-test-file.txt',
          },
          dependencies: ['step_write'],
        },
        {
          id: 'step_git',
          capabilityId: 'git.status',
          input: {
            cwd: '.',
          },
          dependencies: [],
        },
        {
          id: 'step_http',
          capabilityId: 'http.get',
          input: {
            url: 'https://example.com',
          },
          dependencies: [],
        },
        {
          id: 'step_spawn',
          capabilityId: 'process.spawn',
          input: {
            command: 'echo',
            args: ['hello world'],
          },
          dependencies: [],
        },
        {
          id: 'step_wait',
          capabilityId: 'process.wait',
          input: {
            processId: '${step_spawn.output.processId}',
          },
          dependencies: ['step_spawn'],
        },
      ],
    });

    (workflowPlanner as any).invokeLLM = jest
      .fn()
      .mockResolvedValue(mockWorkflowJson);
    // 2. Plan the workflow
    const goal =
      'Perform a smoke test with system.info, files, git, http, and processes';
    const definition = await workflowPlanner.plan(goal);

    expect(definition.steps).toHaveLength(7);
    expect(definition.planningMetadata?.validationResult).toBe('SUCCESS');

    // 3. Submit workflow to engine
    const executionDto = await workflowEngine.submitWorkflow(
      testUserId,
      definition,
      'Smoke Test Workflow',
    );

    // 4. Wait for workflow to finish
    let isComplete = false;
    let finalStatus: WorkflowExecutionStatus = WorkflowExecutionStatus.PENDING;
    let finalState: any = {};

    for (let i = 0; i < 60; i++) {
      const [record] = await db.db
        .select()
        .from(workflowExecutions)
        .where(eq(workflowExecutions.id, executionDto.id));
      if (
        record &&
        (record.status === WorkflowExecutionStatus.SUCCESS ||
          record.status === WorkflowExecutionStatus.FAILED)
      ) {
        isComplete = true;
        finalStatus = record.status as WorkflowExecutionStatus;
        finalState = record.state;
        break;
      }
      await new Promise((res) => setTimeout(res, 500));
    }

    expect(isComplete).toBe(true);
    if (finalStatus !== WorkflowExecutionStatus.SUCCESS) {
      console.log(
        'Workflow failed! Final state:',
        JSON.stringify(finalState, null, 2),
      );
    }
    expect(finalStatus).toBe(WorkflowExecutionStatus.SUCCESS);

    // Assert all steps reached SUCCESS
    expect(finalState['step_info'].status).toBe('SUCCESS');
    expect(finalState['step_write'].status).toBe('SUCCESS');
    expect(finalState['step_read'].status).toBe('SUCCESS');
    expect(finalState['step_git'].status).toBe('SUCCESS');
    expect(finalState['step_http'].status).toBe('SUCCESS');
